INSERT INTO `tabCourse Lesson` VALUES
('0002 testing','2025-10-20 19:05:39.202561','2025-11-08 18:04:40.052142','Administrator','Administrator',0,4,'Apa itu Komputer?',1,'0001 Test',0,'sutradara-animasi','{\"time\":1762599879569,\"blocks\":[{\"id\":\"QgRn9PUz-7\",\"type\":\"header\",\"data\":{\"text\":\"Apa itu Komputer?\",\"level\":2}},{\"id\":\"upFqyrXOk3\",\"type\":\"paragraph\",\"data\":{\"text\":\"Untuk dapat bekerja, Komputer membutuhkan bantuan dari alat-alat yang lain lho!🤔\"}},{\"id\":\"9yl5ZQ0MyF\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"Skg1Hn_AaB\",\"type\":\"paragraph\",\"data\":{\"text\":\"Komputer adalah alat elektronik yang bisa digunakan untuk menampilkan banyak hal seperti gambar, tulisan dan video. 💻Komputer dapat digunakan untuk:\"}},{\"id\":\"HDlCDZfVPK\",\"type\":\"list\",\"data\":{\"style\":\"ordered\",\"items\":[{\"content\":\"Belajar\",\"items\":[]},{\"content\":\"Bermain Game\",\"items\":[]},{\"content\":\"Menonton\",\"items\":[]}]}},{\"id\":\"477FXS598q\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"eJQgn4I3aZ\",\"type\":\"header\",\"data\":{\"text\":\"Komponen dari Komputer\",\"level\":2}},{\"id\":\"KxJZvJWeGJ\",\"type\":\"paragraph\",\"data\":{\"text\":\"Taukah kamu fungsi dari alat-alat dibawah ini?\"}},{\"id\":\"OgBoa9gkir\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/PK1-komponen-komputer.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"NeAxL431rd\",\"type\":\"paragraph\",\"data\":{\"text\":\"Yuk, mari kita tonton video berikut biar lebih kenal apa saja sih bagian-bagian dari sebuah komputer itu 😀\"}},{\"id\":\"FxuOG3wFHZ\",\"type\":\"embed\",\"data\":{\"service\":\"youtube\",\"source\":\"https://youtu.be/difvQyWFmxw?si=HsZ03mTkHZB0a4Kg\",\"embed\":\"difvQyWFmxw\",\"caption\":\"\"}},{\"id\":\"zDw_hjE0qw\",\"type\":\"embed\",\"data\":{\"service\":\"youtube\",\"source\":\"https://youtu.be/Iv8X7aLikLE?si=XPZ8v19WhEFrhdTG\",\"embed\":\"Iv8X7aLikLE\",\"caption\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762599879569,\"blocks\":[{\"id\":\"Oc2YhWWdNP\",\"type\":\"paragraph\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0004 Cara Memakai Mouse','2025-10-20 23:55:00.710506','2025-11-04 13:23:44.709154','Administrator','Administrator',0,0,'Cara Memakai Mouse',1,'0001 Test',0,'sutradara-animasi','{\"time\":1762237424588,\"blocks\":[{\"id\":\"xmyJcYPgEv\",\"type\":\"paragraph\",\"data\":{\"text\":\"Taukah kamu cara menggunakan Mouse?🤔\"}},{\"id\":\"bkKReH67XJ\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/PK1-mouse.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"E_Cmsc9q-Z\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Begini cara memegang mouse👇</b>\"}},{\"id\":\"BtVc_yjwG6\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/PK1-mouse2.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"bYdzvmaFhe\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Mouse Pointer /Kursor :&nbsp;</b>\"}},{\"id\":\"BBTHJgGFkc\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-mouse-pointer.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"N5Bq9E4e8G\",\"type\":\"paragraph\",\"data\":{\"text\":\"Saat kamu menggerakkan mouse, mouse pointer (kursor) di layar juga ikut bergerak lho!😀\"}},{\"id\":\"q0c3NWSumV\",\"type\":\"paragraph\",\"data\":{\"text\":\"Saat koding nanti kita juga akan sering menggunakan mouse.\"}},{\"id\":\"T2HUJE8Acr\",\"type\":\"paragraph\",\"data\":{\"text\":\"Jadi hari ini kita akan latihan agar lebih terampil menggunakan mouse🤩😎\"}},{\"id\":\"zWlfcHN7_o\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762237424589,\"blocks\":[{\"id\":\"eFsXpm9ZTF\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0005 Drag n Drop','2025-10-21 08:07:29.302402','2025-11-04 13:27:33.295136','Administrator','Administrator',0,0,'Drag n Drop',0,'0001 Test',0,'sutradara-animasi','{\"time\":1762237653174,\"blocks\":[{\"id\":\"dlSjHnwck7\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"<b>Dragon Drop</b>\",\"items\":[]}]}},{\"id\":\"NRNPYevdTT\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 080345.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"i66oeK0Ed0\",\"type\":\"paragraph\",\"data\":{\"text\":\"Drag nagamu dan drop pada makanannya, agar ia bisa memakan ayamnya!\"}},{\"id\":\"D1FmH2HqnT\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Main Game </b>: <a href=\\\"https://www.roomrecess.com/games/DragonDrop/play.html\\\">https://www.roomrecess.com/games/DragonDrop/play.html</a>\"}},{\"id\":\"f0HTJ01nj2\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"l4HRr8HDk_\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"<b>Rocket Maze</b>\",\"items\":[]}]}},{\"id\":\"fIYXG5zafD\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 080355.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"uQqGYs7El1\",\"type\":\"paragraph\",\"data\":{\"text\":\"Gunakanlah arrow key untuk menggerakkan bola. Hindari semut agar tidak mengulang dari awal ya!\"}},{\"id\":\"lPldfvQIIv\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Main Game </b>: \"}},{\"id\":\"r1fx8qa_0W\",\"type\":\"markdown\",\"data\":{\"text\":\"<a href=\\\"https://www.happyclicks.net/maze-games/maze_games_soccer.php\\\">https://www.happyclicks.net/maze-games/maze_games_soccer.php</a>\"}},{\"id\":\"TUx2N530j8\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Number Race</b>\"}},{\"id\":\"sopxoFHhGz\",\"type\":\"paragraph\",\"data\":{\"text\":\"Gunakan arrow key untuk menggerakkan mobilmu!\"}},{\"id\":\"5JioaHVEXf\",\"type\":\"paragraph\",\"data\":{\"text\":\"Latih angka ganjil dan genap. Latih lebih besar dari dan lebih kecil dari. Hati-hati! Jawaban yang salah akan mengurangi bahan bakar. Mengemudikan 25 mil untuk kejutan luar biasa!\"}},{\"id\":\"7wFHNbUrmX\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 080415.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"sg7oV_ht_p\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Main Game :</b> <a href=\\\"https://www.abcya.com/games/number_race\\\">https://www.abcya.com/games/number_race</a>\"}},{\"id\":\"9lNccISTqe\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762237653174,\"blocks\":[{\"id\":\"S6A-1R__N4\",\"type\":\"paragraph\",\"data\":{\"text\":\"Kamu akan berlatih dengan permainan untuk melatih logika dan penggunaan muse. Kamu tidak wajib memainkan semua game dan menyelesaikan semuanya ya!\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0006 Coding Review','2025-10-21 08:15:57.958356','2025-11-04 13:44:51.203845','Administrator','Administrator',0,1,'Coding Review ScratchJr',0,'0001 Test',0,'sutradara-animasi','{\"time\":1762238691024,\"blocks\":[{\"id\":\"wU9RuET1IB\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 081212.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"Djnp58GuNW\",\"type\":\"paragraph\",\"data\":{\"text\":\"Pernahkah kalian mencoba aplikasi <b>ScratchJr</b>? 🐱💡\"}},{\"id\":\"kWIOopliYa\",\"type\":\"markdown\",\"data\":{\"text\":\"\\nAplikasi ini seru banget, lho! Dengan ScratchJr, kalian bisa membuat cerita dan permainan sesuai imajinasi kalian sendiri! 🌟🎮&nbsp;&nbsp;\"}},{\"id\":\"j2RBkzp_om\",\"type\":\"paragraph\",\"data\":{\"text\":\"Di dalam ScratchJr, kita menggunakan blok-blok kode berwarna untuk memberi perintah pada karakter.\\nKarakternya bisa bergerak, melompat, menari, bahkan bernyanyi! 💃🎶\"}},{\"id\":\"yLsWBmt1--\",\"type\":\"paragraph\",\"data\":{\"text\":\"Contohnya nih 👇\"}},{\"id\":\"mNAGhbfLf8\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 081222.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"bkPA4NcE8M\",\"type\":\"paragraph\",\"data\":{\"text\":\"Lalu, bagaimana caranya?\"}},{\"id\":\"2NhmmEZA05\",\"type\":\"paragraph\",\"data\":{\"text\":\"Caranya dengan blok kode untuk membuat karakter bergerak, melompat, menari, dan bernyanyi.\"}},{\"id\":\"xm3RSHSEws\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 081236.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"ueZzZg5ncg\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 081242.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"_vBaEaXt-o\",\"type\":\"paragraph\",\"data\":{\"text\":\"Ketika kita menekan bendera hijau 🚩, karakter akan menyapa, lalu mengulangi gerakan sebanyak 4 kali:\\n\"}},{\"id\":\"yz6B4ftQza\",\"type\":\"markdown\",\"data\":{\"text\":\"➡️ 1 kali ke kiri,\\n\"}},{\"id\":\"lB2Ua3c8dO\",\"type\":\"markdown\",\"data\":{\"text\":\"⬅️ 1 kali ke kanan,\\n\"}},{\"id\":\"YJ8l16a-e3\",\"type\":\"markdown\",\"data\":{\"text\":\"🦘 dan lompat 2 kali!\"}},{\"id\":\"OQHv7JK80A\",\"type\":\"paragraph\",\"data\":{\"text\":\"Seru kan? Ayo coba dan lihat bagaimana karaktermu bergerak sesuai kode yang kamu susun! 💻✨\"}},{\"id\":\"UMWH2kEoYy\",\"type\":\"header\",\"data\":{\"text\":\"Ayo kita buat Aquarium!\",\"level\":2}},{\"id\":\"P79WiHoeNU\",\"type\":\"paragraph\",\"data\":{\"text\":\"Buka aplikasi ScratchJr disini ya &gt;&gt; <a href=\\\"https://codejr.org/scratchjr/index.html\\\">ScratchJr</a>\"}},{\"id\":\"5Xh0r_WtOf\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 081250.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"cI8KYwcOCJ\",\"type\":\"markdown\",\"data\":{\"text\":\"&nbsp;1.&nbsp; Siapkan background “Underwater”\"}},{\"id\":\"b0L6gBX5Ku\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;2.&nbsp; Siapkan karakter :\"}},{\"id\":\"7_dBzzm7GL\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 081256.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"xxYIjgHVNU\",\"type\":\"paragraph\",\"data\":{\"text\":\"3.&nbsp; Codinglah Seahorse dengan algoritma berikut menggunakan Loop!\"}},{\"id\":\"NKg7lSqY8s\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 081304.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"DDSdjxmsqZ\",\"type\":\"paragraph\",\"data\":{\"text\":\"4.&nbsp; Cobalah coding karakter lainnya agar bergerak sesuai yang kamu inginkan.\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762238691024,\"blocks\":[{\"id\":\"rDuoE32mfz\",\"type\":\"paragraph\",\"data\":{\"text\":\"Pada pertemuan kali ini kita akan mencoba membuat coding dan animasi dengan ScratchJr!\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0008 Kosakata','2025-10-21 09:33:22.161752','2025-11-04 13:56:06.254758','Administrator','Administrator',0,1,'Mengenal Koding',0,'0007 Apa itu Koding?',0,'sutradara-animasi','{\"time\":1762239366047,\"blocks\":[{\"id\":\"_eZE3mtFaQ\",\"type\":\"header\",\"data\":{\"text\":\"💻 Vocabulary\",\"level\":2}},{\"id\":\"BgUTRmhSWj\",\"type\":\"paragraph\",\"data\":{\"text\":\"🧠<b> Programming</b> adalah bahasa yang digunakan untuk memerintah komputer.\\nDengan Coding, kamu bisa membuat berbagai hal seru seperti:\\n\"}},{\"id\":\"-586mFtGmw\",\"type\":\"markdown\",\"data\":{\"text\":\"✨ Aplikasi atau Website\\n\"}},{\"id\":\"Vq9GiH6WCG\",\"type\":\"markdown\",\"data\":{\"text\":\"🎮 Game\\n\"}},{\"id\":\"07RCgqW4W2\",\"type\":\"markdown\",\"data\":{\"text\":\"🎬 Animasi\"}},{\"id\":\"1qHfBAv6eW\",\"type\":\"paragraph\",\"data\":{\"text\":\"👩‍💻 <b>Programmer / Coder</b> adalah orang yang bisa melakukan programming atau coding.\"}},{\"id\":\"7h5GD6V5KS\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"Lw2MATYxkY\",\"type\":\"paragraph\",\"data\":{\"text\":\"📘 <b>Sequence</b> artinya urutan langkah-langkah.\\n\"}},{\"id\":\"3bzvYqFVfg\",\"type\":\"paragraph\",\"data\":{\"text\":\"🧩<b> Algoritma</b> adalah urutan langkah-langkah dalam coding untuk mencapai tujuan.\"}},{\"id\":\"sR968AowY5\",\"type\":\"paragraph\",\"data\":{\"text\":\"Setiap kegiatan punya urutan langkah-langkahnya, seperti saat menanam bunga 🌼\\nKalau urutannya salah, bunganya tidak akan tumbuh dengan baik 🌱&nbsp;\"}},{\"id\":\"u4Z5NYH0Ik\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-contoh-sequence.jpg\",\"file_type\":\"JPG\",\"quizzes\":[]}},{\"id\":\"usxSiAhbXS\",\"type\":\"paragraph\",\"data\":{\"text\":\"Dalam coding, urutan (algoritma) harus tepat dan tidak boleh salah! ⚙️ Kalau algoritmanya salah, komputer akan bingung membaca perintahnya, dan hasil coding bisa jadi berantakan! 😅\"}},{\"id\":\"6RSDIIpJxr\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762239366047,\"blocks\":[{\"id\":\"aw_w14pXUy\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0009 Coding Review','2025-10-21 09:37:56.780872','2025-11-04 14:10:41.460640','Administrator','Administrator',0,1,'Coding Review',0,'0007 Apa itu Koding?',0,'sutradara-animasi','{\"time\":1762240241260,\"blocks\":[{\"id\":\"USw8dhFd_L\",\"type\":\"paragraph\",\"data\":{\"text\":\"Pada pertemuan kali ini, kita akan belajar membuat coding dan animasi menggunakan ScratchJr untuk menerapkan konsep sequence yang sudah kalian pelajari sebelumnya! 🎮💡\"}},{\"id\":\"JGesNGGXpC\",\"type\":\"paragraph\",\"data\":{\"text\":\"Sekarang, ada tantangan seru nih! 😄\"}},{\"id\":\"1PQ_8JCDju\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/Cuplikan layar 2025-10-21 093727.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"EnsLVJxb4X\",\"type\":\"paragraph\",\"data\":{\"text\":\"Bisakah kalian membantu Naga 🐉 untuk mengambil semua item yang tersebar di dunia ScratchJr?\"}},{\"id\":\"7S9EIoFV_O\",\"type\":\"paragraph\",\"data\":{\"text\":\"Tapi ingat ya, urutan pengambilannya harus tepat! ⏳\\nBerikut urutan yang benar:\\n\"}},{\"id\":\"z5hWD2nucK\",\"type\":\"markdown\",\"data\":{\"text\":\"1️⃣ 🍑 Peach (Buah Persik)\\n\"}},{\"id\":\"T5AE6ZbCUZ\",\"type\":\"markdown\",\"data\":{\"text\":\"2️⃣ 🍎 Apple (Buah Apel)\\n\"}},{\"id\":\"FbGGTJuxjN\",\"type\":\"markdown\",\"data\":{\"text\":\"3️⃣ 🍰 Cake (Kue)\"}},{\"id\":\"DBjAZUD6JU\",\"type\":\"paragraph\",\"data\":{\"text\":\"Susunlah blok-blok kode agar Naga bergerak sesuai urutan di atas.\\nKalau urutannya salah, Naga bisa bingung dan tidak berhasil menyelesaikan misinya! 😅\"}},{\"id\":\"EgORGhb3BN\",\"type\":\"paragraph\",\"data\":{\"text\":\"Ayo, bantu Naga menyelesaikan petualangannya dan tunjukkan kalau kalian sudah paham tentang sequence! 🚀\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762240241261,\"blocks\":[{\"id\":\"24qoKdDxPw\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0015 Quiz Koding 1','2025-10-21 09:57:11.716198','2025-11-04 14:50:27.944558','Administrator','Administrator',0,3,'Quiz Koding 1',0,'0010 Quiz',0,'sutradara-animasi','{\"time\":1762242627730,\"blocks\":[{\"id\":\"g5fIsKMtpB\",\"type\":\"quiz\",\"data\":{\"quiz\":\"quiz-1-coding\"}},{\"id\":\"3EON78E8ki\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762242627730,\"blocks\":[{\"id\":\"osYdrUJqet\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0016 Mari Kita Rawat Gadget Kita','2025-11-04 13:37:24.662238','2025-11-04 13:37:52.333402','Administrator','Administrator',0,0,'Mari Kita Rawat Gadget Kita',0,'0001 Test',0,'sutradara-animasi','{\"time\":1762238272190,\"blocks\":[{\"id\":\"VarG9SWJSH\",\"type\":\"paragraph\",\"data\":{\"text\":\"Apakah kalian suka bermain menggunakan laptop, iPad, atau HP? Semua itu disebut gadget! 📱💻✨\"}},{\"id\":\"Psw-onDHrn\",\"type\":\"paragraph\",\"data\":{\"text\":\"Kalau gadget kalian rusak, pasti sedih ya? 😢\\n\"}},{\"id\":\"441-ya0qiD\",\"type\":\"markdown\",\"data\":{\"text\":\"Makanya, ayo kita belajar cara merawat gadget kita supaya awet dan tetap bisa dipakai belajar serta bermain! 💪🎮📚\"}},{\"id\":\"Y5iACRJxrn\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-rawat-gadget.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"U9HFT4NbVd\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"drFp6ad3cT\",\"type\":\"paragraph\",\"data\":{\"text\":\"🎥 Yuk, tonton video berikut ini untuk tahu cara merawat gadget dengan benar!\"}},{\"id\":\"BZqTkQGV7O\",\"type\":\"embed\",\"data\":{\"service\":\"youtube\",\"source\":\"https://youtu.be/iZbvKhEhmkg?si=goayEKSWA1eIhdQV\",\"embed\":\"iZbvKhEhmkg\",\"caption\":\"\"}},{\"id\":\"2k-_Fbgl6X\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"8LLHL4CK-s\",\"type\":\"paragraph\",\"data\":{\"text\":\"Video Tambahan untuk ditonton:\"}},{\"id\":\"l1zrWk3YUX\",\"type\":\"paragraph\",\"data\":{\"text\":\"<a href=\\\"https://youtu.be/J-4QtEpQ-Ek?si=_P10eW_3aW_iA7aq\\\">Device Advice: How to Care for Your Device</a>\"}},{\"id\":\"kNWbesVKiq\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762238272190,\"blocks\":[{\"id\":\"jAHRH4TOtw\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0017 Sequence dengan ScratchJr','2025-11-04 14:07:55.105895','2025-11-04 14:08:12.673905','Administrator','Administrator',0,0,'Sequence dengan ScratchJr',0,'0007 Apa itu Koding?',0,'sutradara-animasi','{\"time\":1762240092459,\"blocks\":[{\"id\":\"CB5cMPUuQ7\",\"type\":\"paragraph\",\"data\":{\"text\":\"Kalian sudah tahu kan apa itu coding dan sequence? Hebat! 👏\"}},{\"id\":\"5a3QA1a5pg\",\"type\":\"markdown\",\"data\":{\"text\":\"\\nSekarang saatnya kita berlatih langsung dengan membuat coding dan algoritma yang benar! 💻🎯\"}},{\"id\":\"jnYD1rwQDX\",\"type\":\"header\",\"data\":{\"text\":\"1️⃣ Scrat dan Makanannya\\n\",\"level\":2}},{\"id\":\"99P4UiB1Zm\",\"type\":\"paragraph\",\"data\":{\"text\":\"Buatlah coding dengan algoritma yang tepat agar Scrat bisa bergerak menuju makanannya! 🐱🍗\"}},{\"id\":\"WBY75xNSMa\",\"type\":\"header\",\"data\":{\"text\":\"2️⃣ Alien Escape\\n\",\"level\":2}},{\"id\":\"V9yxrLDjg_\",\"type\":\"markdown\",\"data\":{\"text\":\"Susunlah algoritma yang benar supaya Alien bisa menemukan pesawatnya kembali! 👽🚀\"}},{\"id\":\"peTaRJzxy4\",\"type\":\"header\",\"data\":{\"text\":\"3️⃣ Champ the Fruits\\n\",\"level\":2}},{\"id\":\"6Mh3iRJyCb\",\"type\":\"markdown\",\"data\":{\"text\":\"Buatlah coding dengan urutan yang benar agar Monster Ungu bisa mengambil semua buahnya! 🍇🍎🍌\"}},{\"id\":\"4uUO_2KRh1\",\"type\":\"paragraph\",\"data\":{\"text\":\"Ayo tunjukkan seberapa hebat kalian dalam menyusun algoritma! 💪✨\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762240092459,\"blocks\":[{\"id\":\"vkrTky48_y\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0020 Apa itu Internet?','2025-11-04 14:25:13.739188','2025-11-04 14:25:13.739188','Administrator','Administrator',0,0,'Apa itu Internet?',0,'0019 Concept of Debugging & Scratchjr Animation with Sound',0,'sutradara-animasi','{\"time\":1762241113594,\"blocks\":[{\"id\":\"Uk4oUDCXC4\",\"type\":\"paragraph\",\"data\":{\"text\":\"\"}},{\"id\":\"JLJ1u7p_bm\",\"type\":\"paragraph\",\"data\":{\"text\":\"Pernahkah kamu mendengar kata ‘Internet’? 🌍\\n\"}},{\"id\":\"YTUsnRVwKa\",\"type\":\"markdown\",\"data\":{\"text\":\"Tentu pernah dong! Kamu bahkan sering menggunakannya saat bermain game, menonton video, atau mencari gambar lucu! 🎮📺😄\"}},{\"id\":\"TPdjl0qlHU\",\"type\":\"paragraph\",\"data\":{\"text\":\"Sekarang yuk kita kenalan dengan beberapa kata penting (vocabulary) yang berhubungan dengan internet 👇\"}},{\"id\":\"MAZ4s-poGP\",\"type\":\"paragraph\",\"data\":{\"text\":\"💻<b> INTERNET</b>\\nAdalah jaringan dari banyak komputer yang saling terhubung di seluruh dunia 🌐\\nDengan internet, kita bisa berbagi informasi, mengirim pesan, dan mengakses berbagai aplikasi lewat komputer, HP, jam pintar, kamera, dan banyak lagi! ⌚📱📸\"}},{\"id\":\"n958N1n1-u\",\"type\":\"paragraph\",\"data\":{\"text\":\"🔍 <b>BROWSER</b>\\nAdalah tempat untuk mencari informasi di internet.\\nContohnya seperti Google Chrome, Safari, atau Firefox.\\nMelalui browser, kita bisa mengetik dan menemukan apa saja yang ingin kita pelajari! 💡✨\"}},{\"id\":\"viGRun3z1s\",\"type\":\"paragraph\",\"data\":{\"text\":\"Penasaran gak bagaimana internet itu bekerja? Cek video ini ya!\"}},{\"id\":\"fwDSerffKC\",\"type\":\"embed\",\"data\":{\"service\":\"youtube\",\"source\":\"https://youtu.be/UXsomnDkntI\",\"embed\":\"UXsomnDkntI\",\"caption\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762241113594,\"blocks\":[{\"id\":\"g6K9GnBM2a\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0021 Bug & Debugging','2025-11-04 14:33:04.309647','2025-11-04 14:33:04.309647','Administrator','Administrator',0,0,'Bug & Debugging',0,'0019 Concept of Debugging & Scratchjr Animation with Sound',0,'sutradara-animasi','{\"time\":1762241583870,\"blocks\":[{\"id\":\"khEMtPCgwb\",\"type\":\"embed\",\"data\":{\"service\":\"youtube\",\"source\":\"https://youtu.be/__y3BCwDG7M?si=2W99LcucJTZ14mQd\",\"embed\":\"__y3BCwDG7M\",\"caption\":\"\"}},{\"id\":\"vCKOv9bm5F\",\"type\":\"paragraph\",\"data\":{\"text\":\"Pernahkah kamu mengalami coding-mu tidak berjalan seperti yang diinginkan?\\nNah, itu disebut <b>BUG</b>! 🐞\"}},{\"id\":\"ZfleB9fhqj\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Bug</b> adalah kesalahan kecil dalam coding yang membuat program tidak bisa berjalan dengan baik.\\nTapi jangan khawatir! 💪\\nKita bisa membasmi bug dengan cara memperbaiki bagian coding yang salah, nah kegiatan ini disebut <b>debugging</b>! 🧩🔧\"}},{\"id\":\"lpKwhVWdhs\",\"type\":\"paragraph\",\"data\":{\"text\":\"Ayo, jadilah pemburu bug hebat yang selalu sabar dan teliti! 🔍✨\"}},{\"id\":\"lfSxUyZZNW\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"grZzR05DeP\",\"type\":\"header\",\"data\":{\"text\":\"Praktek Debugging!\",\"level\":2}},{\"id\":\"iz6aoggs7G\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Garbage Truck Debugging</b>\"}},{\"id\":\"duBowdsgBc\",\"type\":\"paragraph\",\"data\":{\"text\":\"Kita akan coba bermain game truk sampah ini, klik disini untuk membukanya &gt;&gt; <a href=\\\"https://www.kidlocoding.com/debug/garbagetruck\\\">Garbage Truck</a>\"}},{\"id\":\"hyQyWLZX1p\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-garbage-truck.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"i7-byRD-Yl\",\"type\":\"paragraph\",\"data\":{\"text\":\"Cobalah debugging dengan menambahkan atau menghapus code untuk membuat algoritma yang tepat agar truck bisa mengambil sampahnya!\"}},{\"id\":\"O0pxyu1oKL\",\"type\":\"paragraph\",\"data\":{\"text\":\"HINT : Drag code keluar area untuk menghapusnya!\"}},{\"id\":\"IOD9YuDLWz\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}},{\"id\":\"5fz6-tGzO7\",\"type\":\"paragraph\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762241583870,\"blocks\":[{\"id\":\"nHtQSkfMhG\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0022 Project Sound','2025-11-04 14:48:13.620486','2025-11-07 16:13:06.055471','Administrator','Administrator',0,0,'Project Sound',0,'0019 Concept of Debugging & Scratchjr Animation with Sound',0,'sutradara-animasi','{\"time\":1762506785169,\"blocks\":[{\"id\":\"jJNVPWMkD7\",\"type\":\"paragraph\",\"data\":{\"text\":\"🎧 Sekarang kita akan belajar membuat skrip dengan suara!\\nDi pelajaran kali ini, kalian akan belajar:\\n🎙️ Mengenal blok “<b>Perekaman</b>” dan cara merekam suara.\\n🎬 Membuat skrip paralel, yaitu skrip yang menggabungkan suara dan gerakan secara bersamaan!\"}},{\"id\":\"2H_ifwsprg\",\"type\":\"paragraph\",\"data\":{\"text\":\"Buka ScratchJr disini &gt;&gt; <a href=\\\"https://codejr.org/scratchjr/index.html\\\">Project Sound</a>\"}},{\"id\":\"p1xy1BAWIi\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🪄 Langkah-langkah:</b>\"}},{\"id\":\"0VFnNxFQDd\",\"type\":\"paragraph\",\"data\":{\"text\":\"1️⃣ Tambahkan Karakter Kelinci 🐰\"}},{\"id\":\"Ot4Dda4xVS\",\"type\":\"paragraph\",\"data\":{\"text\":\"\\n2️⃣ Tambahkan Karakter Burung 🐦\\n\"}},{\"id\":\"p16xHlI54p\",\"type\":\"markdown\",\"data\":{\"text\":\"3️⃣ Tambahkan Background Perkotaan 🏙️\"}},{\"id\":\"6Sv6n_Cg8x\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🎤 Membuat Rekaman Suara</b>\"}},{\"id\":\"JX6B2sMp9u\",\"type\":\"paragraph\",\"data\":{\"text\":\"4️⃣ Pilih tombol “Recording” (warna hijau).&nbsp;\"}},{\"id\":\"oLVppYnIhQ\",\"type\":\"image\",\"data\":{\"url\":\"data:image/png;base64,\",\"caption\":\"pk1-sound.png\",\"withBorder\":false,\"withBackground\":false,\"stretched\":false}},{\"id\":\"FBCdUajxlO\",\"type\":\"markdown\",\"data\":{\"text\":\"Saat muncul jendela pop-up, klik “<b>Allow</b>” (Izinkan) untuk memberi akses mikrofon 🎙️\"}},{\"id\":\"AWjH_mIgWk\",\"type\":\"paragraph\",\"data\":{\"text\":\"5️⃣ Klik tombol Record (🔴) seperti pada gambar.\\n\"}},{\"id\":\"bOO7qdPnpQ\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-sound2.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"DIGZLjZuUO\",\"type\":\"markdown\",\"data\":{\"text\":\"Rekam suara burung, kamu bisa:\"}},{\"id\":\"BQNcDe3n5M\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Menirukan suara burung sendiri 🐦🎶\\n\",\"items\":[]},{\"content\":\"Atau memutar suara burung dari speaker yang dekat dengan mikrofon.\",\"items\":[]},{\"content\":\"\",\"items\":[]}]}},{\"id\":\"X-j1-UJUIl\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🌆 Menata dan Memberi Skrip</b>\"}},{\"id\":\"EH8osybvUI\",\"type\":\"paragraph\",\"data\":{\"text\":\"6️⃣ Atur posisi karakter Kelinci dan Burung di panggung seperti pada gambar ini 🪄\"}},{\"id\":\"qVImkSeX1E\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-sound3.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"VDiomD8jI9\",\"type\":\"paragraph\",\"data\":{\"text\":\"7️⃣ Buat skrip untuk Sprite “Burung”\\n\"}},{\"id\":\"yCMLiwGp1L\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-sound4.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"qojS-v-BqA\",\"type\":\"markdown\",\"data\":{\"text\":\"➡️ Gunakan blok suara dan gerakan agar burung berkicau sambil terbang! 🕊️\"}},{\"id\":\"uRqPSIcx7x\",\"type\":\"paragraph\",\"data\":{\"text\":\"8️⃣ Buat skrip untuk Sprite “Kelinci”\\n\"}},{\"id\":\"nFtmq0SjLB\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-sound5.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"I9hJhj2oVF\",\"type\":\"markdown\",\"data\":{\"text\":\"➡️ Atur agar kelinci bergerak atau melompat saat mendengar suara burung 🐰🎶\"}},{\"id\":\"BkyN2V474Z\",\"type\":\"paragraph\",\"data\":{\"text\":\"✨ Sekarang kamu sudah bisa membuat animasi dengan suara dan gerakan sekaligus! Hebat! 🌟💻🎵\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762506785169,\"blocks\":[{\"id\":\"Dj7ApKv_eR\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0024 Apa itu Loop?','2025-11-07 16:23:40.061695','2025-11-07 16:25:37.591801','Administrator','Administrator',0,0,'Apa itu Loop?',0,'0023 Repetition and Loop',0,'sutradara-animasi','{\"time\":1762507536697,\"blocks\":[{\"id\":\"LcPbH7ud2e\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-ice-age.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"x82h9eqByz\",\"type\":\"paragraph\",\"data\":{\"text\":\"Ingatkah kamu dengan permainan di atas? 😄\"}},{\"id\":\"LBTMjPr8I2\",\"type\":\"paragraph\",\"data\":{\"text\":\"Bagaimana cara membuat Scrat bergerak? 🐱\\nNah, kalau Scrat harus berjalan 10 kali, apa yang harus kita lakukan ya? 🤔\"}},{\"id\":\"JvoKPM78b9\",\"type\":\"paragraph\",\"data\":{\"text\":\"Kita bisa menggunakan sesuatu yang disebut<b> LOOP</b>! 🔁\"}},{\"id\":\"QY83eEvrSa\",\"type\":\"embed\",\"data\":{\"service\":\"youtube\",\"source\":\"https://youtu.be/r3Ti5Xp9W8A?si=5KaunqNpIFZKnCE7\",\"embed\":\"r3Ti5Xp9W8A\",\"caption\":\"\"}},{\"id\":\"sMl6hq3rGh\",\"type\":\"paragraph\",\"data\":{\"text\":\"➡️ <b>Loop </b>artinya perulangan.\\nDalam coding, loop digunakan untuk mengulang perintah beberapa kali tanpa harus menulisnya satu per satu. 💡\"}},{\"id\":\"7l59GvMZL2\",\"type\":\"paragraph\",\"data\":{\"text\":\"Contohnya:\\nJika kamu ingin Scrat berjalan 10 langkah, kamu cukup menulis perintah:\\n\"}},{\"id\":\"iBb_DoWlQc\",\"type\":\"markdown\",\"data\":{\"text\":\"🧩 Repeat 10 times → Move forward\"}},{\"id\":\"4sKq1QJKrP\",\"type\":\"paragraph\",\"data\":{\"text\":\"Artinya: “Ulangi perintah maju sebanyak 10 kali.\"}},{\"id\":\"QJSLsV8DOh\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Contoh Penggunaan Kode Loop</b>\"}},{\"id\":\"b8S-R6wLpX\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-loop-contoh.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"oKn_dA_vzY\",\"type\":\"paragraph\",\"data\":{\"text\":\"Hitunglah berapa banyak karakter harus mengulang untuk menyelesaikan tiap tiap aktivitas di atas !\"}},{\"id\":\"ldYv-A4m44\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762507536698,\"blocks\":[{\"id\":\"k7Nhf_G5qY\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0025 Loops with Scrat','2025-11-07 16:24:53.329693','2025-11-07 16:55:49.542911','Administrator','Administrator',0,0,'Loops with Scrat',0,'0023 Repetition and Loop',0,'sutradara-animasi','{\"time\":1762509348941,\"blocks\":[{\"id\":\"Wu8LbDcajh\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🚀 Tantangan Coding: LOOP!</b>\"}},{\"id\":\"76yC_RHtj_\",\"type\":\"paragraph\",\"data\":{\"text\":\"Sekarang saatnya kamu beraksi sebagai programmer cilik hebat! 👩‍💻👦\"}},{\"id\":\"AqWEwD7nku\",\"type\":\"paragraph\",\"data\":{\"text\":\"🎯 Tugasmu:\\nBuatlah coding menggunakan kode LOOP (perulangan) agar Scrat bisa bergerak menuju makanannya! 🐱🍗\"}},{\"id\":\"Vjp278LD6w\",\"type\":\"paragraph\",\"data\":{\"text\":\"Gunakan blok “Repeat” untuk mengulang perintah gerak ke depan beberapa kali.\\n\"}},{\"id\":\"YfYOiYSy_9\",\"type\":\"markdown\",\"data\":{\"text\":\"Contohnya:\\n🧩 Repeat 5 times → Move forward\"}},{\"id\":\"S5Cnt5iJpf\",\"type\":\"paragraph\",\"data\":{\"text\":\"Artinya: “Ulangi perintah maju sebanyak 5 kali” sampai Scratch berhasil mencapai makanannya! 😋\"}},{\"id\":\"pcCnZukINj\",\"type\":\"paragraph\",\"data\":{\"text\":\"💡 Tips:\"}},{\"id\":\"za9hofNKHj\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Hitung dulu berapa langkah yang dibutuhkan Scrat untuk sampai ke makanan.\\n\",\"items\":[]},{\"content\":\"Gunakan blok Repeat agar lebih efisien dan rapi! 🔁✨\\n\",\"items\":[]}]}},{\"id\":\"xXqzUAJ2C0\",\"type\":\"paragraph\",\"data\":{\"text\":\"Ayo, selesaikan misinya dan bantu Scrat makan dengan logika coding yang pintar! 💪🎮\"}},{\"id\":\"P_XTgTsyeJ\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-loop-scrat.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"cVnQhuLqdo\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Main Game Disini</b>: <a href=\\\"https://studio.code.org/courses/coursea-2025/units/1?redirect_warning=true\\\">https://studio.code.org/courses/coursea-2025/units/1?redirect_warning=true</a>\"}},{\"id\":\"y5qrutIelp\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"lR7rul6VKU\",\"type\":\"header\",\"data\":{\"text\":\"Chomp The Fruits\",\"level\":2}},{\"id\":\"i_Xnj6C_xQ\",\"type\":\"paragraph\",\"data\":{\"text\":\"🍓 Tantangan Coding: Chomp The Fruits!\"}},{\"id\":\"U7cLcAkK2v\",\"type\":\"paragraph\",\"data\":{\"text\":\"Kali ini kamu akan membantu karakter Chomp 🟣 untuk mengambil buah stroberi yang lezat! 😋🍓\"}},{\"id\":\"U3Ecu-Wgr-\",\"type\":\"paragraph\",\"data\":{\"text\":\"🎯 Tugasmu:\\nGunakan kode LOOP (perulangan) agar Chomp bisa bergerak berulang kali menuju buah stroberi.\"}},{\"id\":\"c8IKOXzLbE\",\"type\":\"paragraph\",\"data\":{\"text\":\"Contohnya:\\n🧩 Repeat 4 times → Move forward\"}},{\"id\":\"Oslv1zUSkL\",\"type\":\"paragraph\",\"data\":{\"text\":\"Artinya:\\n“Ulangi perintah maju sebanyak 4 kali,” sampai Chomp berhasil mencapai buah stroberi! 🍓👏\"}},{\"id\":\"A422ToZEoE\",\"type\":\"paragraph\",\"data\":{\"text\":\"💡 Tips:\"}},{\"id\":\"vaU1LE5sg5\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Hitung berapa langkah yang dibutuhkan agar Chomp tepat sampai di buahnya.\\n\",\"items\":[]},{\"content\":\"Gunakan blok “Repeat” agar coding-mu lebih singkat dan rapi 🔁✨\\n\",\"items\":[]},{\"content\":\"Tambahkan blok suara atau ekspresi senang saat Chomp berhasil memakan buahnya! 😄🎵\",\"items\":[]}]}},{\"id\":\"AVJ2bai_lU\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1-champ-fruit.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"88XYFJ4z9p\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Main Game Disini:</b>\"}},{\"id\":\"5UP82W1jwD\",\"type\":\"paragraph\",\"data\":{\"text\":\"<a href=\\\"https://www.kidlocoding.com/loops/chompthefruits\\\">https://www.kidlocoding.com/loops/chompthefruits</a>\"}},{\"id\":\"DqPGbhw_B6\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762509348941,\"blocks\":[{\"id\":\"31YoDzPxje\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0031 Quiz Programmer Kecil Beginner 2','2025-11-07 17:01:59.144504','2025-11-07 17:01:59.144504','Administrator','Administrator',0,0,'Quiz Programmer Kecil Beginner 2',0,'0026 Quiz 2',0,'sutradara-animasi','{\"time\":1762509718575,\"blocks\":[{\"id\":\"vHrDHeCxV7\",\"type\":\"quiz\",\"data\":{\"quiz\":\"quiz-2-programmer-kecil-beginner\"}},{\"id\":\"fkxTAivYvq\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762509718575,\"blocks\":[{\"id\":\"xeBKCLNZ2I\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0033 Literasi Digital','2025-11-07 18:26:06.948914','2025-11-07 18:44:08.025704','Administrator','Administrator',0,1,'Etika Digital',1,'0032 Literasi Digital',0,'sutradara-animasi-part-2','{\"time\":1762515847595,\"blocks\":[{\"id\":\"4lUZLQOfz9\",\"type\":\"paragraph\",\"data\":{\"text\":\"Pernahkah kalian mengirim <b>pesan teks secara online</b>?\\nAtau pernah menerima pesan dari seseorang dan merasa orang itu seperti sedang marah padamu? 😟\"}},{\"id\":\"yW3L8VlWeY\",\"type\":\"paragraph\",\"data\":{\"text\":\"Sekarang, coba deh baca ketiga pesan berikut ini 👀\\n\"}},{\"id\":\"PIfJMeEd0N\",\"type\":\"markdown\",\"data\":{\"text\":\"Meskipun kata-katanya sama, tapi cara kita membacanya bisa terasa berbeda, lho! 💬🔊\"}},{\"id\":\"9k1YvN6LqG\",\"type\":\"paragraph\",\"data\":{\"text\":\"🤔 Menurut kalian, kenapa bisa begitu ya?\\n\"}},{\"id\":\"8y9s6Vp8ru\",\"type\":\"markdown\",\"data\":{\"text\":\"Apakah karena nada bicara, tanda baca, atau perasaan saat membaca pesan itu?\"}},{\"id\":\"RQUIm8C6C9\",\"type\":\"paragraph\",\"data\":{\"text\":\"Ayo, kita pelajari bersama bagaimana <b>emosi dan makna</b> bisa berubah dalam pesan teks! 🌈📲\"}},{\"id\":\"d9G-yED-3v\",\"type\":\"embed\",\"data\":{\"service\":\"youtube\",\"source\":\"https://www.youtube.com/watch?v=GHnwpKVMeK8\",\"embed\":\"GHnwpKVMeK8\",\"caption\":\"\"}},{\"id\":\"YdtZYcljkP\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"YOHIwnEemn\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"kmSh2Wa8tg\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"83y58ZDPBP\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762515847595,\"blocks\":[{\"id\":\"BpovbFxTM3\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0034 Copyright, Public Domain, dan Fair Use','2025-11-07 18:31:09.873841','2025-11-07 18:50:32.198484','Administrator','Administrator',0,0,'Copyright, Public Domain, dan Fair Use',1,'0032 Literasi Digital',0,'sutradara-animasi-part-2','{\"time\":1762516231734,\"blocks\":[{\"id\":\"MJawrHLR2F\",\"type\":\"paragraph\",\"data\":{\"text\":\"Ketika kita menggunakan <b>karya orang lain</b>&nbsp;(seperti gambar, musik, video, atau tulisan) ada beberapa <b>hal penting yang harus kita perhatikan</b>:\"}},{\"id\":\"pZ7yEVopWw\",\"type\":\"embed\",\"data\":{\"service\":\"youtube\",\"source\":\"https://www.youtube.com/watch?v=Bdb8kiSmJio\",\"embed\":\"Bdb8kiSmJio\",\"caption\":\"\"}},{\"id\":\"9IPWhEanMo\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"mcKiZ5KgD8\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>1️⃣ Minta izin terlebih dahulu </b>🙋‍♀️\\n\"}},{\"id\":\"9nGqorQNps\",\"type\":\"markdown\",\"data\":{\"text\":\"Jangan asal pakai ya! Pastikan kamu sudah meminta izin kepada pembuatnya sebelum menggunakan karya mereka.\"}},{\"id\":\"WXAlV8awiP\",\"type\":\"paragraph\",\"data\":{\"text\":\"2️⃣ <b>Cantumkan nama pembuatnya</b> ✍️\\n\"}},{\"id\":\"V4Uy1JVtvW\",\"type\":\"markdown\",\"data\":{\"text\":\"Kalau kamu menggunakan karya orang lain, tulis siapa pembuat aslinya. Ini bentuk penghargaan kepada pencipta karya itu.\"}},{\"id\":\"mF7zUrjKYO\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>3️⃣ Jangan mengaku karya sendiri 🚫\\n</b>\"}},{\"id\":\"CePw88sDLH\",\"type\":\"markdown\",\"data\":{\"text\":\"Mengambil karya orang lain dan mengaku itu buatanmu sendiri disebut plagiarisme — dan itu tidak baik.\"}},{\"id\":\"d166mrPVbP\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>4️⃣ Gunakan karya bebas hak cipta (free copyright) 🌍</b>\\n\"}},{\"id\":\"gLWssHul78\",\"type\":\"markdown\",\"data\":{\"text\":\"Beberapa karya di internet bisa digunakan gratis, tapi tetap harus membaca aturan penggunaannya.\"}},{\"id\":\"7r10uoeFZ1\",\"type\":\"paragraph\",\"data\":{\"text\":\"💡 Ingat ya!\\nMenghargai karya orang lain berarti kamu juga belajar menjadi<b> pencipta yang jujur dan bertanggung jawab </b>💖✨\"}},{\"id\":\"lPvXhPXmYq\",\"type\":\"header\",\"data\":{\"text\":\"Apa itu Copyright, Public Domain, dan Fair Use?\",\"level\":2}},{\"id\":\"E-IDRzqM-i\",\"type\":\"table\",\"data\":{\"withHeadings\":false,\"stretched\":false,\"content\":[[\"<b>Istilah</b>\",\"<b>Definisi (Bahasa Indonesia)</b>\"],[\"<i>Copyright</i>\",\"adalah hak cipta atau hukum yang melindungi karya seseorang\"],[\"<i>Public Domain</i>\",\"adalah karya yang tersedia bebas untuk digunakan oleh siapa pun\"],[\"<i>Fair Use</i>\",\"adalah bagian karya yang boleh digunakan secara bebas dalam kondisi atau ketentuan yang telah diatur\"]]}},{\"id\":\"_IKzy9-L6T\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762516231734,\"blocks\":[{\"id\":\"SYQLynrJYW\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0035 Melindungi Karya Sendiri','2025-11-07 18:35:00.681826','2025-11-07 18:35:00.681826','Administrator','Administrator',0,0,'Melindungi Karya Sendiri',0,'0032 Literasi Digital',0,'sutradara-animasi-part-2','{\"time\":1762515300291,\"blocks\":[{\"id\":\"qqSgkUhldo\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🔒 Bagaimana caranya agar karyamu tidak dicuri orang lain?</b>\"}},{\"id\":\"MHM38gI0gz\",\"type\":\"paragraph\",\"data\":{\"text\":\"💡 Tips &amp; Tricks: Menjaga Hak Cipta Karyamu!\\n\"}},{\"id\":\"j2Yoe-9wsZ\",\"type\":\"markdown\",\"data\":{\"text\":\"1️⃣ Tulis namamu pada karya, misalnya: by: [namamu] ✍️\"}},{\"id\":\"s18x1CMIWO\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n2️⃣ Tanda tangani karyamu agar mudah dikenali 🖊️\\n\"}},{\"id\":\"xCAd_OFjAE\",\"type\":\"markdown\",\"data\":{\"text\":\"3️⃣ Beri tanggal pembuatan supaya orang tahu kapan karya itu dibuat 📅\"}},{\"id\":\"q52ToNsdsk\",\"type\":\"paragraph\",\"data\":{\"text\":\"Dengan begitu, orang lain tahu bahwa karya itu milikmu, dan kamu bisa melindunginya dari pencurian! 💪🎨\"}},{\"id\":\"5i0jzAtucW\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}},{\"id\":\"hIfdacvGo7\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🧠 Question Time!</b>\"}},{\"id\":\"ukbWngIbUL\",\"type\":\"paragraph\",\"data\":{\"text\":\"❓ 1. Bolehkah copy-paste artikel dari internet untuk tugas sekolah tanpa mencantumkan sumber?\\n\"}},{\"id\":\"X1XDINUS09\",\"type\":\"markdown\",\"data\":{\"text\":\"🚫 Tidak boleh! Karena itu termasuk plagiarisme, yaitu mengambil karya orang lain tanpa izin.\\n✅ Sebaiknya, tulis ulang dengan kata-katamu sendiri dan cantumkan sumbernya agar tetap jujur dan menghargai pembuat aslinya.\"}},{\"id\":\"CElHzIxErt\",\"type\":\"paragraph\",\"data\":{\"text\":\"❓ 2. Bolehkah mengakui lagu seseorang sebagai milik kita?\\n\"}},{\"id\":\"CBopkne8cq\",\"type\":\"markdown\",\"data\":{\"text\":\"🚫 Tidak boleh! Itu sama saja seperti mencuri ide dan karya orang lain.\\n🎵 Tindakan ini bisa merugikan pencipta aslinya, karena mereka kehilangan penghargaan dan mungkin juga penghasilan dari karyanya.\"}},{\"id\":\"wB-uoSbvO2\",\"type\":\"paragraph\",\"data\":{\"text\":\"❓ 3. Bolehkah membuat versi tiruan dari merek atau brand tertentu?\\n\"}},{\"id\":\"JGLdT2t755\",\"type\":\"markdown\",\"data\":{\"text\":\"🚫 Tidak boleh juga! Membuat tiruan merek bisa disebut pelanggaran hak cipta atau merek dagang.\\n🏷️ Hal ini bisa membuat pemilik merek aslinya rugi dan bisa berurusan dengan hukum.\"}},{\"id\":\"biBsavw-6E\",\"type\":\"paragraph\",\"data\":{\"text\":\"✨ Ingat ya!\\nMenjadi kreator berarti kamu harus <b>jujur, menghargai karya orang lain, dan bangga dengan hasil karyamu sendiri</b>. 🌟\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762515300291,\"blocks\":[{\"id\":\"9ZnN0jrIe0\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0036 Screen Time','2025-11-07 18:48:27.593829','2025-11-07 18:48:27.593829','Administrator','Administrator',0,0,'Screen Time',0,'0032 Literasi Digital',0,'sutradara-animasi-part-2','{\"time\":1762516107113,\"blocks\":[{\"id\":\"XlRn0qNMbe\",\"type\":\"paragraph\",\"data\":{\"text\":\"&nbsp;Apakah kalian suka bermain dengan handphone atau laptop? 🤔\\nBerapa lama, ya, kalian biasanya bermain gadget dalam sehari?&nbsp;&nbsp;\"}},{\"id\":\"FlnZohfNI8\",\"type\":\"paragraph\",\"data\":{\"text\":\"Tonton video berikut, yuk!\"}},{\"id\":\"101o5O0Toe\",\"type\":\"embed\",\"data\":{\"service\":\"youtube\",\"source\":\"https://www.youtube.com/watch?v=4f8KUqUWaBI\",\"embed\":\"4f8KUqUWaBI\",\"caption\":\"\"}},{\"id\":\"TMfxWyA7pG\",\"type\":\"paragraph\",\"data\":{\"text\":\"Jadi menurut kalian apa itu<b> Screen Time?</b>\"}},{\"id\":\"nhSzLgt7Gu\",\"type\":\"table\",\"data\":{\"withHeadings\":true,\"content\":[[\"Istilah\",\"Definisi (Bahasa Indonesia)\"],[\"<i>Gadget Addiction</i>\",\"Kecanduan terhadap gadget seperti handphone, laptop, atau game konsol. 🎮📱\"],[\"<i>Screen Time</i>\",\"Waktu yang dihabiskan untuk menatap layar, seperti saat bermain game, menonton, atau belajar online. 🕒\"]]}},{\"id\":\"yV-oLpu6Jl\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}},{\"id\":\"dTCbNmzWyu\",\"type\":\"header\",\"data\":{\"text\":\"⏰ Yuk, Catat Waktu Bermainmu!\",\"level\":2}},{\"id\":\"oF7CPqa_TH\",\"type\":\"paragraph\",\"data\":{\"text\":\"Selama satu minggu, coba catat berapa lama kamu bermain gadget setiap hari.\\nGunakan tabel di bawah ini, ya! 👇\"}},{\"id\":\"CsXMTUX-4Q\",\"type\":\"table\",\"data\":{\"withHeadings\":false,\"content\":[[\"Hari/Tanggal\",\"Lama Bermain\",\"Kegiatan Pengganti Bermain Gadget\"]]}},{\"id\":\"orMdcpfld1\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762516107113,\"blocks\":[{\"id\":\"Oo9Dl01Nus\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0038 Grid with ScratchJr','2025-11-07 18:56:25.535769','2025-11-08 18:45:14.347929','Administrator','Administrator',0,0,'Grid with ScratchJr',0,'0037 Grid & Go To',0,'sutradara-animasi-part-2','{\"time\":1762602314047,\"blocks\":[{\"id\":\"QwTMWe2fCt\",\"type\":\"header\",\"data\":{\"text\":\"🧩 Masih Ingatkah Kamu Dengan ScratchJr?\",\"level\":1}},{\"id\":\"E94XLGFoJq\",\"type\":\"paragraph\",\"data\":{\"text\":\"Tahukah kamu apa fungsi Mode Grid di ScratchJr? 🤔\"}},{\"id\":\"eZDsIeeQxW\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>📍 Mode Grid </b>membantu kita melihat posisi karakter di layar!\\nDalam Grid, ada dua garis penting:\"}},{\"id\":\"eTExqF15IM\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"<b>Koordinat X </b>➡️ menunjukkan posisi <b>mendatar (kiri–kanan)</b>\\n\",\"items\":[]},{\"content\":\"<b>Koordinat Y </b>⬆️ menunjukkan posisi <b>tegak lurus (atas–bawah)</b>\",\"items\":[]}]}},{\"id\":\"4qSWY0eVoE\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-grid.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"e1mYUOPY0l\",\"type\":\"paragraph\",\"data\":{\"text\":\"✨ Kali ini, kita akan belajar menentukan posisi karakter menggunakan Grid Mode!\"}},{\"id\":\"WXTcna_WiB\",\"type\":\"paragraph\",\"data\":{\"text\":\"🖱️ Untuk melihat posisi karakter:\\nAktifkan<b> Mode Grid</b> yang ada di bagian atas layar ScratchJr.\"}},{\"id\":\"7U95y603HN\",\"type\":\"paragraph\",\"data\":{\"text\":\"🔎 Setelah itu, coba tebak — di mana posisi X dan Y dari karakter di bawah ini?\\nApakah dia berada di tengah? Di pojok kanan? Atau di bawah? 🤓\"}},{\"id\":\"QlTigoOz20\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-grid2.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"P7T-gPVYEa\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762602314047,\"blocks\":[{\"id\":\"DknM249CT1\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0039 Flying to The Moon','2025-11-07 19:09:49.702092','2025-11-08 18:45:58.682343','Administrator','Administrator',0,0,'Flying to The Moon',0,'0037 Grid & Go To',0,'sutradara-animasi-part-2','{\"time\":1762602358356,\"blocks\":[{\"id\":\"tbAgyuRV7a\",\"type\":\"paragraph\",\"data\":{\"text\":\"Saatnya membuat animasi roket terbang ke bulan di ScratchJr!\\nIkuti langkah-langkah di bawah ini, ya! 👇\"}},{\"id\":\"GrpYGQWlWN\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🪄 Langkah 1 – Add Pages</b>\"}},{\"id\":\"19AX5FnVRD\",\"type\":\"paragraph\",\"data\":{\"text\":\"Siapkan<b> 3 halaman (Page) dan tambahkan karakter Roket</b> di setiap halaman seperti petunjuk berikut:\"}},{\"id\":\"zpZe4QoJxX\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🧭 Page 1</b>\"}},{\"id\":\"FWxNLp4cFM\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-flymon1.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"iHqXcny_xV\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Aktifkan Mode Grid.\",\"items\":[]},{\"content\":\"Letakkan Roket di posisi X:11, Y:6.\",\"items\":[]}]}},{\"id\":\"csyH7ajiOf\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-flymon4.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"fotB74jLNN\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Buat coding dengan algoritma berikut:\",\"items\":[]}]}},{\"id\":\"7Ppu-FI-nn\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-flymon5.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"633zfDO243\",\"type\":\"paragraph\",\"data\":{\"text\":\"Ketika Rocket di <b>tap</b>, Rocket <b>naik ke Y:15</b>, Karakter <b>menghilang</b>, Pindah<b> ke Page 2</b>\"}},{\"id\":\"7OlUXpa-B-\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Pindahlah ke <b>Page 2</b>, kemudian tambahkan karakter <b>Rocket</b> dan<b> 4 awan</b>!\",\"items\":[]}]}},{\"id\":\"wQ1_MuLcEz\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-flymon6.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"MTnDHCH5Ny\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Letakkan Rocket di <b>posisi X:11, Y:1 </b>dan awan-awan di sekitarnya!\",\"items\":[]},{\"content\":\"Buatlah coding pada<b> Rocket </b>dengan algoritma di bawah!\\n\",\"items\":[]}]}},{\"id\":\"X5qg76Fhvm\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-flymon7.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"Wmo8YvL4BO\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Buatlah coding pada semua awan dengan algoritma di bawah:\",\"items\":[]}]}},{\"id\":\"BDz_quOa3_\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-flymon8.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"AJTRrLrVld\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Ketika</b> dimulai,\"}},{\"id\":\"zynYIlfrsP\",\"type\":\"paragraph\",\"data\":{\"text\":\"Awan <b>turun (15)</b>\"}},{\"id\":\"25tkg8hf8u\",\"type\":\"paragraph\",\"data\":{\"text\":\"Pindahlah ke <b>Page 3</b>, kemudian tambahkan karakter <b>Rocket</b>!\"}},{\"id\":\"cgA3V1vYXS\",\"type\":\"paragraph\",\"data\":{\"text\":\"Letakkan Rocket di posisi<b> X:11, Y:15</b>\"}},{\"id\":\"73XQLEG7EF\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-flymon9.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"nEgNk_jEOi\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}},{\"id\":\"Cma3HE1v0h\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Buatlah coding pada <b>Rocket</b> dengan algoritma di bawah:\",\"items\":[]}]}},{\"id\":\"LyMxmLmSLE\",\"type\":\"markdown\",\"data\":{\"text\":\"Ketika dimulai,\"}},{\"id\":\"aOhW3ykWBW\",\"type\":\"paragraph\",\"data\":{\"text\":\"Rocket turun ke X:11 Y:6\"}},{\"id\":\"-9IKWxBeKK\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}},{\"id\":\"E-4mNyEwXZ\",\"type\":\"paragraph\",\"data\":{\"text\":\"🎉 Sekarang, jalankan animasimu!\\nLihat bagaimana roketmu terbang tinggi menembus awan dan menuju bulan! 🌙💫\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762602358356,\"blocks\":[{\"id\":\"dqGqePz7yg\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0046 Quiz 1: Programmer Kecil Beginner Part 2','2025-11-08 19:00:26.146452','2025-11-08 19:00:36.694569','Administrator','Administrator',0,0,'Quiz 1: Programmer Kecil Beginner Part 2',0,'0041 Quiz 1: Programmer Kecil Beginner Part 2',0,'sutradara-animasi-part-2','{\"time\":1762603236482,\"blocks\":[{\"id\":\"ondg6FCJmO\",\"type\":\"quiz\",\"data\":{\"quiz\":\"quiz-1-programmer-kecil-beginner-part-2\"}},{\"id\":\"OEC5MFaHdC\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762603236482,\"blocks\":[{\"id\":\"hHBZmquFfU\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0048 Message in ScratchJr','2025-11-08 19:10:29.140666','2025-11-08 19:10:29.140666','Administrator','Administrator',0,0,'Message in ScratchJr',0,'0047 Animation Racing in Scratch Jr',0,'sutradara-animasi-part-2','{\"time\":1762603828965,\"blocks\":[{\"id\":\"6yLnfiILJl\",\"type\":\"header\",\"data\":{\"text\":\"💬 Yuk, Kenalan dengan Block Code \\\"Message\\\" di ScratchJr!\",\"level\":1}},{\"id\":\"HrUHk1Jm4z\",\"type\":\"paragraph\",\"data\":{\"text\":\"Apakah kamu masih ingat dengan ScratchJr? 🤔\\nNah, kali ini kita akan belajar tentang block code “<b>Message</b>”! 💌\"}},{\"id\":\"uMAr9-BJo4\",\"type\":\"paragraph\",\"data\":{\"text\":\"🧩 Apa itu <b>Message</b>?\\n\"}},{\"id\":\"1QeRK0ubG-\",\"type\":\"paragraph\",\"data\":{\"text\":\"Block code <b>Message</b> berfungsi untuk <b>mengirim pesan antar karakter</b> di ScratchJr.\\nKetika satu karakter mengirim pesan, karakter lain bisa <b>bergerak </b>atau <b>menjalankan coding secara otomatis</b> begitu pesan itu diterima! 🚀💬\"}},{\"id\":\"FjO4OlX_lO\",\"type\":\"paragraph\",\"data\":{\"text\":\"Contohnya:\"}},{\"id\":\"D4S1WWJDNH\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Saat Kucing selesai berjalan, ia mengirim pesan ke Anjing.\\n\",\"items\":[]},{\"content\":\"Lalu Anjing pun langsung bergerak! 🐱➡️🐶\\n\",\"items\":[]}]}},{\"id\":\"U6axBZpxbf\",\"type\":\"paragraph\",\"data\":{\"text\":\"Dengan Message Block, kamu bisa membuat cerita atau animasi yang terlihat hidup dan saling terhubung! 🎬✨\"}},{\"id\":\"0N44XhSB-I\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Start on Message</b>\"}},{\"id\":\"QZqE2DA5tv\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-start message.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"VK74Ru2Mnm\",\"type\":\"paragraph\",\"data\":{\"text\":\"Gambar itu untuk memulai kode setiap kali message dengan warna yang ditentukan dikirim.\"}},{\"id\":\"2_vU5lYpiB\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Send Message</b>\"}},{\"id\":\"2dWHsg_e2f\",\"type\":\"upload\",\"data\":{\"file_url\":\"/files/pk1.2-send message.png\",\"file_type\":\"PNG\",\"quizzes\":[]}},{\"id\":\"kR_QxS1BIP\",\"type\":\"paragraph\",\"data\":{\"text\":\"Untuk mengirim Message dengan warna yang ditentukan.\"}},{\"id\":\"pVF3oOemjD\",\"type\":\"markdown\",\"data\":{\"text\":\"\\n\\n\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762603828965,\"blocks\":[{\"id\":\"mAaCC_rfDi\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL),
('0049 Membuat Message di ScratchJr','2025-11-08 19:24:15.275318','2025-11-08 22:31:14.740231','Administrator','Administrator',0,0,'Membuat Message di ScratchJr',0,'0047 Animation Racing in Scratch Jr',0,'sutradara-animasi-part-2','{\"time\":1762615874411,\"blocks\":[{\"id\":\"-IA6tTEVbu\",\"type\":\"header\",\"data\":{\"text\":\"🐾 Yuk, Buat Game “Animal Race” di ScratchJr! 🏁\",\"level\":2}},{\"id\":\"8UpoeS7pUv\",\"type\":\"paragraph\",\"data\":{\"text\":\"Kali ini kita akan membuat <b>permainan seru </b>dengan menggunakan block code “<b>Message</b>”! 💬\"}},{\"id\":\"56MlHye2zI\",\"type\":\"paragraph\",\"data\":{\"text\":\"Game ini bernama “<b>Animal Race</b>”, lomba lari hewan di padang Savannah! 🐰🦊🐢\"}},{\"id\":\"oDa49gLjtk\",\"type\":\"markdown\",\"data\":{\"text\":\"Ikuti langkah-langkahnya dengan cermat, ya! 👇\"}},{\"id\":\"sU9rDiIzLC\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>✨ Step 1: Buat Project Baru</b>\"}},{\"id\":\"wd5smKl9vg\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Buka aplikasi ScratchJr.\",\"items\":[]}]}},{\"id\":\"tQkDh0mIN0\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Pilih Project Baru (+) untuk memulai dari awal.\",\"items\":[]}]}},{\"id\":\"mEdbN2hG5s\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🌄 Step 2: Ubah Background</b>\"}},{\"id\":\"km2SpeMrY_\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"items\":[{\"content\":\"Klik ikon Latar Belakang (Background).\",\"items\":[]}]}},{\"id\":\"RimN_S0lim\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>🧩 Step 3: Tambahkan Karakter Hewan</b>\"}},{\"id\":\"eFdzD7aWaT\",\"type\":\"paragraph\",\"data\":{\"text\":\"Tambahkan tiga karakter hewan: 🐘 Elephant, 🦒 Giraffe, dan 🐵 Monkey \"}},{\"id\":\"AuVZ8FfaxN\",\"type\":\"markdown\",\"data\":{\"text\":\"Semua hewan ini masih terlalu besar, kan? Yuk, kita kecilkan ukurannya! \"}},{\"id\":\"kRskKwTl8M\",\"type\":\"markdown\",\"data\":{\"text\":\"Kalau semua hewan sudah mengecil dengan ukuran yang sama, 🧹 hapus block code “Shrink” supaya coding-mu tetap rapi! ✨\"}}],\"version\":\"2.31.0-rc.7\"}','','{\"time\":1762615874411,\"blocks\":[{\"id\":\"c2skWNl9Mn\",\"type\":\"markdown\",\"data\":{\"text\":\"\"}}],\"version\":\"2.31.0-rc.7\"}','',NULL,NULL,NULL,'',NULL,NULL,NULL,NULL);
