INSERT INTO `tabLMS Course` VALUES
('arsitek-game-arcade','2025-10-21 00:04:59.756995','2025-11-18 22:00:09.329672','Administrator','Administrator',0,0,'Arsitek Game Arcade','','Beginner','Programmer Muda','In Progress','/files/programmer-muda-beginner.png','Red',0,NULL,1,0,1,'Menerapkan dan menganalisis','<ul><li><p style=\"text-align: justify;\"><span><strong>Misi Level:</strong> Menguasai fondasi logika pemrograman untuk merancang dan membangun <em>game arcade</em> yang seru dan responsif dari awal hingga akhir.</span></p></li><li><p style=\"text-align: justify;\"><span><strong>Target Taksonomi <em>Bloom</em>:</strong> Menerapkan (<em>Applying</em>) &amp; Menganalisis (<em>Analyzing</em>).</span></p></li></ul>',0,1,0,0.000000000,'',0.000000000,'',NULL,0,0,'0.0',NULL,NULL,NULL,NULL),
