INSERT INTO `tabNotification` VALUES
('Certificate Request Reminder','2022-06-03 11:51:02.681803','2025-07-04 10:47:58.448814','Administrator','Administrator',0,0,1,1,'LMS','Email',NULL,'Reminder for Certificate Evaluation','Days Before','LMS Certificate Request',NULL,'date',NULL,1,0,NULL,NULL,NULL,0,NULL,NULL,'doc.status == \"Upcoming\"',NULL,NULL,NULL,0,'HTML','<p> {{ _(\"Hey {0}\").format(doc.member_name) }} </p>\n<br>\n<p> {{ _(\'Your evaluation for the course {0} has been scheduled on {1} at {2} {3}.\').format(doc.course_title, frappe.utils.format_date(doc.date, \"medium\"), frappe.utils.format_time(doc.start_time, \"short\"), doc.timezone) }}</p>\n<br>\n<p> {{ _(\"{0} is your evaluator\").format(doc.evaluator_name) }} </p>\n<br>\n<p> {{ _(\"Please prepare well and be on time for the evaluations.\") }} </p>\n',0,NULL,NULL,NULL,NULL,NULL),
('New job alert','2021-12-30 12:29:56.533903','2021-12-30 12:54:13.382512','Administrator','Administrator',0,0,1,1,'Job','Email',NULL,'New job added by {{ doc.company_name}}','New','Job Opportunity',NULL,NULL,NULL,0,0,NULL,NULL,NULL,0,'',NULL,NULL,NULL,NULL,NULL,0,NULL,'Hey,\n\nA new Job Opportunity has been created. \n\n<p>Company Name: {{ doc.company_name}}</p>\n<p>Job Title: {{ doc.job_title}}</p>\n<p>Job Location: {{ doc.location}}</p><br>\n<p>Job Description: {{ doc.description}}</p><br>\n\n<p>Find all the posted jobs  <a href=\"{{ frappe.utils.get_url() }}/app/job-opportunity\">here</a>.</p><br>\n',0,NULL,NULL,NULL,NULL,NULL);
